# Author: KK
# Version: v1.1(2026-4-9)
# PowerShell script to update nds32-ae210p.sag based on sys_em.cfg
# Usage: powershell -ExecutionPolicy Bypass -File update_sag.ps1
# Note: sys_em.cfg is generated by gcc preprocessing and contains all macro definitions
# Enhanced version with full Windows 7 / PowerShell 2.0 compatibility

param(
    [string]$ConfigFile = "",
    [string]$SagFile = ""
)

# Get current working directory (where script.bat is executed from, typically Release/)
$currentDir = Get-Location

# Check PowerShell version and compatibility
$psVersion = $PSVersionTable.PSVersion
Write-Host "PowerShell Version: $($psVersion.Major).$($psVersion.Minor).$($psVersion.Build)"

# Check execution policy (helpful for troubleshooting)
try {
    $execPolicy = Get-ExecutionPolicy -Scope CurrentUser -ErrorAction SilentlyContinue
    if ($execPolicy -eq 'Restricted') {
        Write-Warning "Execution policy is Restricted. If script fails, run: Set-ExecutionPolicy RemoteSigned -Scope CurrentUser"
    }
} catch {
    # Ignore errors in policy check - script can still run with -ExecutionPolicy Bypass
}

# Set default paths if not provided
# sys_em.cfg is typically in Release/ directory
if ([string]::IsNullOrEmpty($ConfigFile)) {
    $ConfigFile = "sys_em.cfg"
}
if ([string]::IsNullOrEmpty($SagFile)) {
    $SagFile = "..\nds32-ae210p.sag"
}

# Resolve relative paths to absolute paths
try {
    # Resolve-Path returns PathInfo; normalize to plain string for PS2/.NET IO APIs
    $ConfigFile = (Resolve-Path $ConfigFile -ErrorAction Stop).Path
    $SagFile = (Resolve-Path $SagFile -ErrorAction Stop).Path
} catch {
    Write-Error "Failed to resolve file paths: $_"
    Write-Host "Current directory: $currentDir"
    Write-Host "ConfigFile: $ConfigFile"
    Write-Host "SagFile: $SagFile"
    exit 1
}

# Function to evaluate C expression (simple cases)
# Fully compatible with PowerShell 2.0 and .NET 3.5
function Evaluate-ExpressionImpl {
    param([string]$expr)
    
    # PowerShell 2.0 compatibility: use IsNullOrEmpty and regex instead of IsNullOrWhiteSpace
    if ([string]::IsNullOrEmpty($expr) -or $expr -match '^\s*$') {
        return 0
    }
    
    # Remove comments (compatible regex - no non-greedy matching for PS2 compatibility)
    $expr = $expr -replace '//.*$', ''
    $expr = $expr -replace '/\*', ''
    $expr = $expr -replace '\*/', ''
    
    # Remove parentheses and whitespace
    $expr = $expr.Trim() -replace '[()\s]', ''
    
    # Handle multiplication (e.g., 44*1024, 12*1024)
    if ($expr -match '(\d+)\*(\d+)') {
        $val1 = [int]$matches[1]
        $val2 = [int]$matches[2]
        return $val1 * $val2
    }
    
    # Handle simple number
    if ($expr -match '^\d+$') {
        return [int]$expr
    }
    
    Write-Warning "Could not evaluate expression: $expr, using 0"
    return 0
}

# Function to extract macro value from sys_em.cfg file
# sys_em.cfg is generated by gcc -E -dM -P, so all conditionals are already resolved
function Get-MacroValue {
    param(
        [string]$filePath,
        [string]$macroName
    )
    
    if (-not (Test-Path $filePath)) {
        Write-Error "Config file not found: $filePath"
        return $null
    }
    
    # Read all lines and find the macro definition
    # Format: #define MACRO_NAME value
    $lines = Get-Content $filePath
    
    foreach ($line in $lines) {
        $trimmedLine = $line.Trim()
        
        # Match #define MACRO_NAME value
        if ($trimmedLine -match "^#define\s+$macroName\s+(.+)$") {
            $value = $matches[1].Trim()
            
            # Remove inline comments (though sys_em.cfg shouldn't have them)
            $value = $value -replace '//.*$', ''
            # PowerShell 2.0 compatibility: use greedy matching instead of non-greedy
            $value = $value -replace '/\*.*\*/', ''
            $value = $value.Trim()
            
            return $value
        }
    }
    
    return $null
}

# Main execution
Write-Host "Reading configuration from: $ConfigFile"
Write-Host "Updating SAG file: $SagFile"

# Get macro values
$bbEmSize = Get-MacroValue -filePath $ConfigFile -macroName "BB_EM_SIZE"
$tcmSize = Get-MacroValue -filePath $ConfigFile -macroName "TCM_SIZE"
$stackSize = Get-MacroValue -filePath $ConfigFile -macroName "STACK_SIZE"
$core2RamSize = Get-MacroValue -filePath $ConfigFile -macroName "CORE2_RAM_SIZE"

if ($null -eq $bbEmSize -or $null -eq $tcmSize -or $null -eq $stackSize -or $null -eq $core2RamSize) {
    Write-Error "Failed to extract macro values from config file"
    Write-Host "BB_EM_SIZE: $bbEmSize"
    Write-Host "TCM_SIZE: $tcmSize"
    Write-Host "STACK_SIZE: $stackSize"
    Write-Host "CORE2_RAM_SIZE: $core2RamSize"
    exit 1
}

Write-Host "BB_EM_SIZE = $bbEmSize"
Write-Host "TCM_SIZE = $tcmSize"
Write-Host "STACK_SIZE = $stackSize"
Write-Host "CORE2_RAM_SIZE = $core2RamSize"

# Evaluate expressions
$bbEmSizeVal = Evaluate-ExpressionImpl $bbEmSize
$tcmSizeVal = Evaluate-ExpressionImpl $tcmSize
$stackSizeVal = Evaluate-ExpressionImpl $stackSize
$core2RamSizeVal = Evaluate-ExpressionImpl $core2RamSize

Write-Host "Evaluated values:"
Write-Host "  BB_EM_SIZE = $bbEmSizeVal bytes"
Write-Host "  TCM_SIZE = $tcmSizeVal bytes"
Write-Host "  STACK_SIZE = $stackSizeVal bytes"
Write-Host "  CORE2_RAM_SIZE = $core2RamSizeVal bytes"

# Calculate new address: 0x20000000 + BB_EM_SIZE + TCM_SIZE + STACK_SIZE + CORE2_RAM_SIZE
$baseAddr = 0x20000000
$newAddr = $baseAddr + $bbEmSizeVal + $tcmSizeVal + $stackSizeVal + $core2RamSizeVal
$newAddrHex = "0x{0:X}" -f $newAddr

Write-Host "Calculated new address: $newAddrHex ($newAddr)"

# Read SAG file
if (-not (Test-Path $SagFile)) {
    Write-Error "SAG file not found: $SagFile"
    exit 1
}

# Read file as raw bytes first so we can preserve encoding/BOM exactly
$fileBytes = [System.IO.File]::ReadAllBytes($SagFile)

# Detect UTF-8 BOM
$hasUtf8Bom = $false
if ($fileBytes.Length -ge 3 -and $fileBytes[0] -eq 0xEF -and $fileBytes[1] -eq 0xBB -and $fileBytes[2] -eq 0xBF) {
    $hasUtf8Bom = $true
}

# Decode bytes:
# - If BOM exists: decode as UTF-8 from byte 3
# - Else: try strict UTF-8 (throw on invalid), fallback to system Default (ANSI)
$decodedAs = "utf8"
$utf8Strict = New-Object System.Text.UTF8Encoding($false, $true)
try {
    if ($hasUtf8Bom) {
        $sagContentRaw = $utf8Strict.GetString($fileBytes, 3, $fileBytes.Length - 3)
    } else {
        $sagContentRaw = $utf8Strict.GetString($fileBytes)
    }
} catch {
    $decodedAs = "default"
    $sagContentRaw = [System.Text.Encoding]::Default.GetString($fileBytes)
}

$sagLines = $sagContentRaw -split "`r?`n"

# Update EXEC_SDRAM and STACK lines
$execSdramUpdated = $false
$stackUpdated = $false
$newLines = @()

foreach ($line in $sagLines) {
    $originalLine = $line
    
    # Match EXEC_SDRAM 0x2000E000 or similar - preserve original formatting exactly
    # Only replace the hex address, keep everything else (indentation, spacing, etc.)
    if ($line -match '^(\s*EXEC_SDRAM\s+)(0x[0-9A-Fa-f]+)(\s*.*)$') {
        $prefix = $matches[1]  # Everything before the address (including original indentation)
        $suffix = $matches[3]  # Everything after the address
        $line = "$prefix$newAddrHex$suffix"
        $execSdramUpdated = $true
        Write-Host "Updated EXEC_SDRAM: $originalLine -> $line"
    }
    # Match STACK = 0x2000E000 or similar - preserve original formatting exactly
    elseif ($line -match '^(\s*STACK\s*=\s*)(0x[0-9A-Fa-f]+)(\s*.*)$') {
        $prefix = $matches[1]  # Everything before the address (including original indentation)
        $suffix = $matches[3]  # Everything after the address
        $line = "$prefix$newAddrHex$suffix"
        $stackUpdated = $true
        Write-Host "Updated STACK: $originalLine -> $line"
    }
    
    $newLines += $line
}

$updated = $execSdramUpdated -or $stackUpdated

if (-not $updated) {
    Write-Warning "No EXEC_SDRAM or STACK lines found to update"
    exit 1
}

# Write back preserving original line endings
# Detect original line ending style from original content
$lineEnding = if ($sagContentRaw -match "`r`n") { "`r`n" } elseif ($sagContentRaw -match "`n") { "`n" } else { "`r`n" }
$newContent = $newLines -join $lineEnding

# Preserve whether original file ended with a line ending
$hadFinalNewline = $false
if ($sagContentRaw.Length -gt 0) {
    if ($sagContentRaw.EndsWith("`r`n") -or $sagContentRaw.EndsWith("`n") -or $sagContentRaw.EndsWith("`r")) {
        $hadFinalNewline = $true
    }
}
if ($hadFinalNewline) {
    $newContent = $newContent + $lineEnding
}

# Write back with preserved encoding/BOM choice
# - If decoded as Default: write Default (no BOM)
# - If decoded as UTF-8: preserve BOM presence exactly
$writeEncoding = $null
if ($decodedAs -eq "default") {
    $writeEncoding = [System.Text.Encoding]::Default
} else {
    $writeEncoding = New-Object System.Text.UTF8Encoding($hasUtf8Bom)
}

# PowerShell 2.0 compatibility: StreamWriter is the most reliable way here
$streamWriter = New-Object System.IO.StreamWriter($SagFile, $false, $writeEncoding)
$streamWriter.Write($newContent)
$streamWriter.Close()
$streamWriter.Dispose()

Write-Host "Successfully updated $SagFile"
exit 0
